<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Response\QuestionCommentResponseDto;use App\Application\QuestionLearning\Mapper\QuestionCommentResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Repository\QuestionCommentRepositoryInterface;
final readonly class ListQuestionCommentsService { public function __construct(private FrozenQuestionReaderInterface $questions, private QuestionCommentRepositoryInterface $comments, private QuestionCommentResponseMapper $mapper) {} /** @return array{items:list<QuestionCommentResponseDto>,total:int,page:int,perPage:int} */ public function execute(string $questionId, int $page, int $perPage): array { if ($page < 1 || $perPage < 1 || $perPage > 100) { throw new \InvalidArgumentException('Paginação inválida.'); } if (count($this->questions->findByIds([$questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } return ['items' => array_map($this->mapper->toResponse(...), $this->comments->listForQuestion($questionId, $page, $perPage)), 'total' => $this->comments->countForQuestion($questionId), 'page' => $page, 'perPage' => $perPage]; } }
